package ru.mentalarena;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static ru.mentalarena.Db.*;
import static ru.mentalarena.Input.*;
@Service
public class Marathons {
 final Db db;final Auth auth;final Clock clock;
 Marathons(Db db,Auth auth,Clock clock){this.db=db;this.auth=auth;this.clock=clock;}
 public Map<String,Object> access(Map<String,Object> u,String mid,boolean write){var m=db.one("select * from marathons where id=?",mid);if(s(u,"role").equals("ADMIN"))return m;if(s(u,"role").equals("TEACHER")&&db.maybe("select user_id from marathon_teachers where marathon_id=? and user_id=?",mid,s(u,"id")).isPresent())return m;if(!write&&s(u,"role").equals("PARENT")&&db.maybe("select c.id from children c join enrollments e on e.child_id=c.id where e.marathon_id=? and c.parent_id=?",mid,s(u,"id")).isPresent())return m;forbidden();return m;}
 public Map<String,Object> ownChild(Map<String,Object> u,String cid){var c=db.one("select * from children where id=?",cid);if(!s(c,"parent_id").equals(s(u,"id")))forbidden();return c;}
 public LocalDate today(Map<String,Object> m){return LocalDate.now(clock.withZone(ZoneId.of(s(m,"timezone"))));}
 public Instant opens(Map<String,Object> m,int day){return ((LocalDate)m.get("start_date")).plusDays(day-1).atStartOfDay(ZoneId.of(s(m,"timezone"))).toInstant();}
 public String effectiveStatus(Map<String,Object> m){String status=s(m,"status");if(Set.of("DRAFT","CANCELLED").contains(status))return status;LocalDate today=today(m),start=(LocalDate)m.get("start_date");return today.isBefore(start)?"SCHEDULED":today.isBefore(start.plusDays(n(m,"days")))?"ACTIVE":"COMPLETED";}
 @Transactional public Map<String,Object> child(Map<String,Object> u,Map<String,Object> body){auth.parent(u);String cid=id();db.run("insert into children values(?,?,?,?,?,?,?)",cid,s(u,"id"),text(body,"lastName",80),text(body,"firstName",80),optional(body,"middleName",80),number(body,"birthYear",LocalDate.now(clock).getYear()-25,LocalDate.now(clock).getYear()),choice(body,"category","BABY","SCHOOL"));auth.audit(s(u,"id"),"CHILD_CREATED",cid,"Добавлен профиль ребёнка");return db.one("select * from children where id=?",cid);}
 @Transactional public Map<String,Object> create(Map<String,Object> u,Map<String,Object> body){auth.staff(u);String mid=id(),timezone=optional(body,"timezone",80);if(timezone.isEmpty())timezone="Europe/Moscow";ZoneId.of(timezone);LocalDate start=LocalDate.parse(text(body,"startDate",10));int days=body.containsKey("days")?number(body,"days",1,31):6;String code=UUID.randomUUID().toString().replace("-","").substring(0,12).toUpperCase(Locale.ROOT);db.run("insert into marathons values(?,?,?,?,?,?,?,?,?,?)",mid,text(body,"title",150),optional(body,"description",2000),start,days,timezone,"DRAFT",b(body,"published"),code,s(u,"id"));db.run("insert into marathon_teachers values(?,?)",mid,s(u,"id"));auth.audit(s(u,"id"),"MARATHON_CREATED",mid,"Создан марафон");return db.one("select * from marathons where id=?",mid);}
 @Transactional public void update(Map<String,Object> u,String mid,Map<String,Object> body){var m=access(u,mid,true);String status=body.containsKey("status")?choice(body,"status","DRAFT","SCHEDULED","CANCELLED"):s(m,"status");if(status.equals("DRAFT"))require(db.maybe("select t.id from attempts t join assignments a on a.id=t.assignment_id where a.marathon_id=?",mid).isEmpty(),"Начавшийся марафон нельзя вернуть в черновик");db.run("update marathons set title=?,description=?,published=?,status=? where id=?",body.containsKey("title")?text(body,"title",150):m.get("title"),body.containsKey("description")?optional(body,"description",2000):m.get("description"),body.containsKey("published")?b(body,"published"):b(m,"published"),status,mid);auth.audit(s(u,"id"),"MARATHON_UPDATED",mid,"Настройки и статус");}
 @Transactional public void teacher(Map<String,Object> u,String mid,String uid){auth.admin(u);access(u,mid,true);var teacher=db.one("select * from users where id=?",uid);require(Set.of("TEACHER","ADMIN").contains(s(teacher,"role")),"Нужна роль педагога");if(db.maybe("select * from marathon_teachers where marathon_id=? and user_id=?",mid,uid).isEmpty())db.run("insert into marathon_teachers values(?,?)",mid,uid);auth.audit(s(u,"id"),"TEACHER_ASSIGNED",mid,uid);}
 @Transactional public void join(Map<String,Object> u,Map<String,Object> body){auth.parent(u);require(b(u,"verified"),"Сначала подтвердите телефон");var c=ownChild(u,text(body,"childId",36));String code=text(body,"code",16).toUpperCase(Locale.ROOT);var m=db.one("select * from marathons where join_code=?",code);require(!Set.of("CANCELLED","COMPLETED").contains(effectiveStatus(m)),"Приём участников закрыт");if(db.maybe("select * from enrollments where marathon_id=? and child_id=?",s(m,"id"),s(c,"id")).isPresent())return;db.run("insert into enrollments values(?,?)",s(m,"id"),s(c,"id"));auth.audit(s(u,"id"),"ENROLLED",s(c,"id"),s(m,"id"));auth.queue(s(u,"id"),"enrolled:"+s(m,"id")+":"+s(c,"id"),"Считай: ребёнок добавлен в марафон «"+s(m,"title")+"».",false);}
 public Map<String,Object> dashboard(Map<String,Object> u){List<Map<String,Object>> ms;if(s(u,"role").equals("ADMIN"))ms=db.list("select * from marathons order by start_date desc");else if(s(u,"role").equals("TEACHER"))ms=db.list("select m.* from marathons m join marathon_teachers t on t.marathon_id=m.id where t.user_id=? order by start_date desc",s(u,"id"));else ms=db.list("select distinct m.* from marathons m join enrollments e on e.marathon_id=m.id join children c on c.id=e.child_id where c.parent_id=? order by start_date desc",s(u,"id"));ms.forEach(m->{m.put("effective_status",effectiveStatus(m));if(s(u,"role").equals("PARENT"))m.remove("join_code");});return Map.of("children",s(u,"role").equals("PARENT")?db.list("select * from children where parent_id=? order by first_name",s(u,"id")):List.of(),"marathons",ms);}
 public Map<String,Object> detail(Map<String,Object> u,String mid){var m=access(u,mid,false);List<Map<String,Object>> children=s(u,"role").equals("PARENT")?db.list("select c.* from children c join enrollments e on e.child_id=c.id where e.marathon_id=? and c.parent_id=? order by last_name",mid,s(u,"id")):db.list("select c.* from children c join enrollments e on e.child_id=c.id where e.marathon_id=? order by last_name",mid);var assignments=new ArrayList<Map<String,Object>>();for(var c:children){for(var a:db.list("select a.*,t.status as attempt_status,t.correct,t.errors,t.skipped,t.started_at,t.finished_at,t.deadline from assignments a left join attempts t on t.id=a.current_attempt where a.marathon_id=? and a.child_id=? order by a.day",mid,s(c,"id"))){a.put("opens_at",opens(m,n(a,"day")));a.put("closes_at",opens(m,n(a,"day")+1));assignments.add(a);}}m.put("effective_status",effectiveStatus(m));if(s(u,"role").equals("PARENT"))m.remove("join_code");return Map.of("marathon",m,"children",children,"assignments",assignments,"teachers",s(u,"role").equals("PARENT")?List.of():db.list("select u.id,u.full_name from users u join marathon_teachers t on t.user_id=u.id where t.marathon_id=?",mid));}
}
